class switch_driver extends uvm_driver #(switch_item); `uvm_component_utils(switch_driver) virtual switch_if vif; function new(string n,uvm_component p);super.new(n,p);endfunction function void build_phase(uvm_phase phase); if(!uvm_config_db#(virtual switch_if)::get(this,"","vif",vif)) `uvm_fatal("NOVIF","switch_if missing") endfunction task run_phase(uvm_phase phase); vif.in_valid<='0; forever begin seq_item_port.get_next_item(req); drive(req); seq_item_port.item_done(); end endtask task drive(switch_item t); @(posedge vif.clk); vif.in_valid[t.src]<=1; vif.in_data[t.src]<=t.data; vif.in_dst[t.src]<=t.dst; do @(posedge vif.clk); while(!vif.in_ready[t.src]); vif.in_valid[t.src]<=0; endtask endclass
